	/** 
	 * jumpstart the process by instantiating2 Rate
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		rateId = RateService.getRateInstance()
		.createRate( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		RateService.getRateInstance()
				.createRate( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.rateSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Rate : " + successValue.getRateId());
							  if (successValue.getRateId().equals(rateId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfRateList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Rate test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on rate consumed")
					);
			subscriber.rateSubscribe( rateId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Rate : " + successValue.getRateId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfRateList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on rate for rateId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Rate. 
	 */
	protected Rate read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Rate" );

		Rate entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Rate with primary key" );
		msg.append( rateId );
		
		RateFetchOneSummary fetchOneSummary = new RateFetchOneSummary( rateId );

		try {
			entity = RateService.getRateInstance().getRate( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Rate " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Rate.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Rate." );

		StringBuilder msg = new StringBuilder( "Failed to update a Rate : " );        
		Rate entity = read();
		UpdateRateCommand command = generateUpdateCommand();
		command.setRateId(entity.getRateId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Rate." );

			// for use later on...
			rateId = entity.getRateId();

			RateService proxy = RateService.getRateInstance();  

			proxy.updateRate( command ).get();

			LOGGER.info( "-- Successfully saved Rate - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + rateId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Rate.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Rate." );

		Rate entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Rate with id " + rateId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Rate with id " + rateId );

			throw e;
		}

		try{
			RateService.getRateInstance().delete( new DeleteRateCommand( entity.getRateId() ) ).get();
			LOGGER.info( "-- Successfully deleted Rate with id " + rateId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Rate with id " + rateId );

			throw e;
		}
	}

	/**
	 * get all Rates.
	 */
	protected List<Rate> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Rates:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Rate : " );        
		List<Rate> collection  = new ArrayList<>();

		try {
			// call the static get method on the RateService
			collection = RateService.getRateInstance().getAllRate();
			assertNotNull( collection, "An Empty collection of Rate was incorrectly returned.");
			
			// Now print out the values
			Rate entity = null;            
			Iterator<Rate> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRateId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

